// ─── Clients — Depth (Sprint 5) ──────────────────────────────────────────────

export interface NewClientsByMonthPoint {
  /** ISO month string e.g. "2026-01" */
  month: string
  count: number
}

export interface CohortRetentionRow {
  /** Display label e.g. "Jan 2026" */
  cohort: string
  /** ISO month string used as key e.g. "2026-01" */
  cohortKey: string
  /** Number of clients who joined this cohort */
  cohortSize: number
  /**
   * Retention percentages for follow-on months N+1 through N+6.
   * Each value is 0–100 (integer). null means the cohort is too recent
   * for that follow-on month to have elapsed yet.
   */
  retentions: Array<number | null>
}

/** LTV histogram bucket. min/max in cents; max=null for the top bucket. */
export interface LtvBucket {
  /** Display label e.g. "$0–100" */
  bucket: string
  min: number
  max: number | null
  count: number
}

// ─── Bookings — Depth (Sprint 5) ─────────────────────────────────────────────

