'use client'

/**
 * CohortHeatmap
 *
 * Renders a cohort retention grid:
 *   Y axis: cohort month labels (e.g. "Jan 2026 (24)")
 *   X axis: N+1 through N+6 (follow-on months)
 *   Cell: retention % with Stone→Onyx→Rust brand ramp
 *   Null cells (follow-on month in future): Stone outline, no fill
 *
 * A11y: full ARIA grid roles. Each cell is focusable with descriptive label.
 * Mobile: parent overflow-x-auto; cells stay fixed readable size (min-w-max).
 */

import type { CohortRetentionRow } from '@/lib/types/analytics'

const FOLLOW_ON_LABELS = ['N+1', 'N+2', 'N+3', 'N+4', 'N+5', 'N+6'] as const

export interface CohortHeatmapProps {
  data: CohortRetentionRow[]
}

/**
 * Brand-locked color ramp: Stone (low) → Onyx (mid) → Rust (high / peak).
 * Null cells = Stone outline only.
 */
function cellStyle(
  value: number | null,
  max: number,
): { backgroundColor?: string; border?: string; color: string } {
  if (value === null) {
    return {
      backgroundColor: 'transparent',
      border: '1px solid color-mix(in oklch, var(--color-stone) 30%, transparent)',
      color: 'transparent',
    }
  }
  if (value === 0 || max === 0) {
    return {
      backgroundColor: 'color-mix(in oklch, var(--color-stone) 8%, transparent)',
      color: 'var(--color-stone)',
    }
  }
  const intensity = value / max
  if (intensity >= 1) {
    // Peak cell → Rust
    return {
      backgroundColor: 'color-mix(in oklch, var(--color-rust) 85%, transparent)',
      color: 'var(--color-bone)',
    }
  }
  if (intensity >= 0.5) {
    // Mid-high → Onyx ramp 50–85%
    const pct = Math.round(50 + intensity * 35)
    return {
      backgroundColor: `color-mix(in oklch, var(--color-onyx) ${pct}%, transparent)`,
      color: intensity >= 0.65 ? 'var(--color-bone)' : 'var(--color-onyx)',
    }
  }
  // Low → Stone tint 10–45%
  const pct = Math.round(10 + intensity * 70)
  return {
    backgroundColor: `color-mix(in oklch, var(--color-stone) ${pct}%, transparent)`,
    color: 'var(--color-onyx)',
  }
}

export function CohortHeatmap({ data }: CohortHeatmapProps) {
  // Compute max retention across all non-null cells for normalisation
  const allValues = data.flatMap((row) => row.retentions).filter((v): v is number => v !== null)
  const max = allValues.length > 0 ? Math.max(...allValues, 1) : 1

  return (
    <div className="overflow-x-auto">
      <div
        role="grid"
        aria-label="Cohort retention heatmap — follow-on month booking rates"
        className="inline-flex flex-col gap-1 min-w-max"
      >
        {/* Column header row */}
        <div role="row" className="flex items-center gap-1 pl-1">
          {/* Spacer for cohort label column */}
          <div className="w-32 shrink-0" aria-hidden="true" />
          {FOLLOW_ON_LABELS.map((label) => (
            <div
              key={label}
              role="columnheader"
              aria-label={`Follow-on month ${label}`}
              className="w-14 text-center text-[10px] font-semibold text-muted-foreground uppercase tracking-wide select-none"
            >
              {label}
            </div>
          ))}
        </div>

        {/* Cohort rows */}
        {data.map((row) => (
          <div key={row.cohortKey} role="row" className="flex items-center gap-1">
            {/* Cohort label */}
            <div
              role="rowheader"
              className="w-32 shrink-0 pr-2 text-right text-[11px] font-medium text-foreground/80 select-none leading-tight"
            >
              <span className="block">{row.cohort}</span>
              {row.cohortSize > 0 && (
                <span className="text-[10px] text-muted-foreground tabular-nums">
                  ({row.cohortSize})
                </span>
              )}
            </div>

            {/* Retention cells */}
            {row.retentions.map((value, n) => {
              const followLabel = FOLLOW_ON_LABELS[n] ?? `N+${n + 1}`
              const isNull = value === null

              const ariaLabel = isNull
                ? `${row.cohort} cohort, ${followLabel}: not applicable yet`
                : value === 0
                ? `${row.cohort} cohort, ${followLabel}: 0% returned`
                : `${row.cohort} cohort, ${followLabel}: ${value}% returned (${Math.round((value / 100) * row.cohortSize)} of ${row.cohortSize})`

              const style = cellStyle(value, max)

              return (
                <div
                  key={n}
                  role="gridcell"
                  tabIndex={0}
                  aria-label={ariaLabel}
                  title={ariaLabel}
                  className="h-9 w-14 rounded flex items-center justify-center text-[11px] font-semibold tabular-nums outline-none focus-visible:ring-1 focus-visible:ring-[var(--color-rust)] focus-visible:ring-offset-1 cursor-default select-none transition-colors"
                  style={{
                    backgroundColor: style.backgroundColor,
                    border: style.border,
                    color: style.color,
                  }}
                >
                  {isNull ? '' : `${value}%`}
                </div>
              )
            })}
          </div>
        ))}
      </div>

      <p className="mt-3 text-xs text-muted-foreground">
        Retention = % of cohort who booked in that follow-on month. Outlined cells are future months.
      </p>
    </div>
  )
}

'use client'

/**
 * LtvHistogram
 *
 * Recharts BarChart — 5 LTV buckets displayed as vertical bars.
 * Brand-locked: Stone-tinted bars, Onyx text, Bone background.
 * Sorted ascending by min (leftmost = lowest bucket).
 * Tooltip: "$100–500: 47 clients · 31% of total"
 */

import {
  BarChart,
  Bar,
  CartesianGrid,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  Cell,
} from 'recharts'
import type { LtvBucket } from '@/lib/types/analytics'
import { useChartTheme } from '@/lib/charts/theme'

export interface LtvHistogramProps {
  data: LtvBucket[]
}

interface TooltipPayloadItem {
  value: number
  payload: LtvBucket & { pct: number }
}

interface CustomTooltipProps {
  active?: boolean
  payload?: TooltipPayloadItem[]
}

function CustomTooltip({ active, payload }: CustomTooltipProps) {
  if (!active || !payload || payload.length === 0) return null
  const item = payload[0]
  if (!item) return null
  const { value, payload: data } = item
  return (
    <div
      className="rounded-md border bg-[var(--color-bone)] px-3 py-2 text-xs shadow-[var(--shadow-lift)]"
      style={{ borderColor: 'var(--color-border)' }}
    >
      <p className="font-semibold text-foreground">{data.bucket}</p>
      <p className="mt-0.5 text-muted-foreground tabular-nums">
        {value} {value === 1 ? 'client' : 'clients'} &middot; {data.pct}% of total
      </p>
    </div>
  )
}

export function LtvHistogram({ data }: LtvHistogramProps) {
  const ct = useChartTheme()

  // Sort ascending by min to ensure correct left-to-right order
  const sorted = [...data].sort((a, b) => a.min - b.min)

  const total = sorted.reduce((s, b) => s + b.count, 0)

  const chartData = sorted.map((b) => ({
    ...b,
    pct: total > 0 ? Math.round((b.count / total) * 100) : 0,
  }))

  return (
    <ResponsiveContainer width="100%" height={200}>
      <BarChart data={chartData} margin={{ top: 4, right: 4, bottom: 0, left: -20 }}>
        <CartesianGrid strokeDasharray="3 3" stroke={ct.grid} vertical={false} />
        <XAxis
          dataKey="bucket"
          tick={{ fontSize: 10, fill: ct.text }}
          tickLine={false}
          axisLine={{ stroke: ct.axis }}
          interval={0}
        />
        <YAxis
          tick={{ fontSize: 11, fill: ct.text }}
          tickLine={false}
          axisLine={{ stroke: ct.axis }}
          allowDecimals={false}
        />
        <Tooltip content={<CustomTooltip />} cursor={{ fill: ct.grid, opacity: 0.6 }} />
        <Bar dataKey="count" radius={[3, 3, 0, 0]}>
          {chartData.map((entry, index) => (
            <Cell
              key={index}
              fill={`color-mix(in oklch, var(--color-stone) ${entry.count > 0 ? 55 : 15}%, transparent)`}
            />
          ))}
        </Bar>
      </BarChart>
    </ResponsiveContainer>
  )
}

