  }))

  const priorChartData = priorData?.map((p) => ({
    name: shortMonthLabel(p.month),
    value: p.count,
  }))

  return (
    <RechartsAreaChart
      data={chartData}
      dataKey="value"
      label="New clients"
      formatValue={(v) => String(v)}
      {...(priorChartData && priorChartData.length > 0
        ? { priorData: priorChartData, priorLabel }
        : {})}
    />
  )
}

