import { useCallback } from 'react'
import { useSearchParams } from 'next/navigation'
import { useQuery } from '@tanstack/react-query'
import { Users, UserPlus, Repeat, DollarSign, TrendingUp, Grid, BarChart2 } from 'lucide-react'
import { KpiCard } from '@/components/shared/KpiCard'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { DataState } from '@/components/shared/DataState'
import { EmptyState } from '@/components/shared/EmptyState'
import { TableSkeleton } from '@/components/skeletons'
import { Skeleton } from '@/components/ui/skeleton'
import { formatCurrency, formatPercent, computeDelta } from '@/lib/utils'
import { useExportCsv } from '@/hooks/use-export-csv'
import { CohortHeatmap } from '@/components/reports/charts/CohortHeatmap'
import { LtvHistogram } from '@/components/reports/charts/LtvHistogram'
import { NewClientsLine } from '@/components/reports/charts/NewClientsLine'
import type {
  NewClientsByMonthPoint,
  CohortRetentionRow,
  LtvBucket,
} from '@/lib/types/analytics'

interface ClientsBlock {
  totalClients: number
  newClients: number
  returningClients: number
  inactiveClients: number
  avgLtv: number
  retentionRate: number
  newClientsByMonth: NewClientsByMonthPoint[]
  cohortRetention: CohortRetentionRow[]
  ltvDistribution: LtvBucket[]
}

interface ClientsResponse {
  current: ClientsBlock
  prior?: ClientsBlock
}

function trendOf(delta: number | null): 'up' | 'down' | 'neutral' {
  if (delta === null) return 'neutral'
  return delta > 0 ? 'up' : delta < 0 ? 'down' : 'neutral'
}

export function ClientsReportClient() {
  const searchParams = useSearchParams()
  const from = searchParams.get('from') ?? ''
  const to = searchParams.get('to') ?? ''
  const compare = searchParams.get('compare') ?? '0'

  const { data, isLoading, error } = useQuery<ClientsResponse>({
    queryKey: ['reports', 'clients', from, to, compare],
    queryFn: () => {
      const params = new URLSearchParams()
      if (from) params.set('from', from)
      if (to) params.set('to', to)
      if (compare === '1') params.set('compare', '1')
      return fetch(`/api/reports/clients?${params.toString()}`).then((r) => r.json())
    },
    staleTime: 5 * 60 * 1000,
  })

  const getRows = useCallback(() => {
    if (!data?.current) return []
    const d = data.current
    return [
      { metric: 'Total Clients', value: String(d.totalClients) },
      { metric: 'New Clients', value: String(d.newClients) },
      { metric: 'Retention Rate', value: `${d.retentionRate}%` },
      { metric: 'Avg LTV', value: formatCurrency(d.avgLtv) },
    ]
  }, [data])

  useExportCsv({
    filename: 'analytics-clients',
    getRows,
    headers: { metric: 'Metric', value: 'Value' },
  })

  return (
    <DataState
      data={data}
      isLoading={isLoading}
      isError={!!error}
      error={error instanceof Error ? error : null}
      loadingSlot={<TableSkeleton rows={5} />}
      emptySlot={
        <EmptyState
          icon={Users}
          title="No client data yet"
          description="Client retention metrics will appear after their first visit."
          variant="default"
        />
      }
    >
      {(resp) => {
        const d = resp.current
        const prior = resp.prior
        const showDeltas = compare === '1' && prior !== undefined

        const totalDeltaRaw = computeDelta(d.totalClients, prior?.totalClients)
        const newDeltaRaw = computeDelta(d.newClients, prior?.newClients)
        const retentionDeltaRaw = computeDelta(d.retentionRate, prior?.retentionRate)
        const ltvDeltaRaw = computeDelta(d.avgLtv, prior?.avgLtv)

        const totalDelta = showDeltas ? formatPercent(totalDeltaRaw) : null
        const newDelta = showDeltas ? formatPercent(newDeltaRaw) : null
        const retentionDelta = showDeltas ? formatPercent(retentionDeltaRaw) : null
        const ltvDelta = showDeltas ? formatPercent(ltvDeltaRaw) : null

        const priorLabel = 'vs prior period'

        return (
          <div className="space-y-6">
            {/* 4 KPI cards */}
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
              <KpiCard
                label="Total Clients"
                value={d.totalClients}
                subtextLabel={totalDelta ? priorLabel : 'all time'}
                icon={Users}
                trend={trendOf(totalDeltaRaw)}
                index={0}
                {...(totalDelta !== null ? { delta: totalDelta } : {})}
              />
              <KpiCard
                label="New This Period"
                value={d.newClients}
                subtextLabel={newDelta ? priorLabel : 'first booking only'}
                icon={UserPlus}
                trend={trendOf(newDeltaRaw)}
                index={1}
                {...(newDelta !== null ? { delta: newDelta } : {})}
              />
              <KpiCard
                label="Retention Rate"
                value={`${d.retentionRate}%`}
                subtextLabel={retentionDelta ? priorLabel : 'return after first visit'}
                icon={Repeat}
                trend={trendOf(retentionDeltaRaw)}
                index={2}
                {...(retentionDelta !== null ? { delta: retentionDelta } : {})}
              />
              <KpiCard
                label="Avg LTV"
                value={formatCurrency(d.avgLtv)}
                subtextLabel={ltvDelta ? priorLabel : 'lifetime value per client'}
                icon={DollarSign}
                trend={trendOf(ltvDeltaRaw)}
                index={3}
                {...(ltvDelta !== null ? { delta: ltvDelta } : {})}
              />
            </div>

            {/* New clients trend — full-width */}
            <Card className="border-border/50 shadow-[var(--shadow-card)]">
              <CardHeader>
                <CardTitle className="flex items-center gap-2 text-sm font-medium">
                  <TrendingUp className="h-4 w-4 text-muted-foreground" aria-hidden="true" />
                  New Clients per Month
                </CardTitle>
              </CardHeader>
              <CardContent>
                {d.newClientsByMonth.every((p) => p.count === 0) ? (
                  <EmptyState
                    icon={TrendingUp}
                    title="No new-client trend yet"
                    description="Data will accumulate as clients are added over time."
                    size="sm"
                    compact
                  />
                ) : (
                  <NewClientsLine
                    data={d.newClientsByMonth}
                    {...(showDeltas && prior?.newClientsByMonth
                      ? { priorData: prior.newClientsByMonth, priorLabel }
                      : {})}
                  />
                )}
              </CardContent>
            </Card>

            {/* Cohort heatmap + LTV histogram — side by side on large screens */}
            <div className="grid gap-6 lg:grid-cols-2">
              <Card className="border-border/50 shadow-[var(--shadow-card)]">
                <CardHeader>
                  <CardTitle className="flex items-center gap-2 text-sm font-medium">
                    <Grid className="h-4 w-4 text-muted-foreground" aria-hidden="true" />
                    Cohort Retention
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  {d.cohortRetention.length === 0 ||
                  d.cohortRetention.every((row) => row.cohortSize === 0) ? (
                    <EmptyState
                      icon={Grid}
                      title="No cohort data yet"
                      description="Retention heatmap builds up as clients complete multiple sessions over months."
                      size="sm"
                      compact
                    />
                  ) : (
                    <CohortHeatmap data={d.cohortRetention} />
                  )}
                </CardContent>
              </Card>

              <Card className="border-border/50 shadow-[var(--shadow-card)]">
                <CardHeader>
                  <CardTitle className="flex items-center gap-2 text-sm font-medium">
                    <BarChart2 className="h-4 w-4 text-muted-foreground" aria-hidden="true" />
                    LTV Distribution
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  {d.ltvDistribution.every((b) => b.count === 0) ? (
                    <EmptyState
                      icon={BarChart2}
                      title="No LTV data yet"
                      description="LTV distribution appears once clients have completed bookings."
                      size="sm"
                      compact
                    />
                  ) : (
                    <LtvHistogram data={d.ltvDistribution} />
                  )}
                </CardContent>
              </Card>
            </div>
          </div>
        )
      }}
    </DataState>
  )
}

'use client'

import { useCallback, useState } from 'react'
import { useSearchParams } from 'next/navigation'
import { useQuery } from '@tanstack/react-query'
import { CalendarDays, TrendingDown, ArrowUpDown, ArrowUp, ArrowDown } from 'lucide-react'
import { KpiCard } from '@/components/shared/KpiCard'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { Skeleton } from '@/components/ui/skeleton'
import { DataState } from '@/components/shared/DataState'
import { EmptyState } from '@/components/shared/EmptyState'
import { ChartSkeleton } from '@/components/skeletons'
import { useExportCsv } from '@/hooks/use-export-csv'
import { BookingsHeatmap } from '@/components/reports/charts/BookingsHeatmap'
import { StatusBreakdownBar } from '@/components/reports/charts/StatusBreakdownBar'
import type { StatusSegment } from '@/components/reports/charts/StatusBreakdownBar'
import { formatCurrency, formatPercent, computeDelta } from '@/lib/utils'
import type { ServiceRankItem, SourceBreakdown } from '@/lib/types/analytics'
import dynamic from 'next/dynamic'

const RechartsBarChart = dynamic(() => import('./RechartsBarChart'), {
  ssr: false,
  loading: () => <Skeleton className="h-56 w-full" />,
})

interface BookingKpis {
  total: number
  completed: number
  noShows: number
  cancelled: number
  noShowRate: number
  cancellationRate: number
}

interface StatusBreakdown {
  completed: number
  no_show: number
  cancelled: number
  pending: number
  confirmed: number
  in_progress: number
  rescheduled: number
  other: number
}

interface BookingsBlock {
  kpis: BookingKpis
  statusBreakdown: StatusBreakdown
  timeline: Array<{ period: string; count: number }>
  heatmap: number[][]
  serviceRanking: ServiceRankItem[]
  sourceBreakdown: SourceBreakdown
}

interface BookingsResponse {
  current: BookingsBlock
  prior?: BookingsBlock
}

// ─── Sort state types ────────────────────────────────────────────────────────

type SortKey = 'count' | 'revenueCents' | 'avgTicketCents' | 'noShowRate'
type SortDir = 'asc' | 'desc'

function sortServices(
  rows: ServiceRankItem[],
  key: SortKey,
  dir: SortDir,
): ServiceRankItem[] {
  return [...rows].sort((a, b) => {
    const aVal = a[key]
    const bVal = b[key]
    return dir === 'asc' ? aVal - bVal : bVal - aVal
  })
}

// ─── Sub-components ──────────────────────────────────────────────────────────

function SortIcon({ active, dir }: { active: boolean; dir: SortDir }) {
  if (!active) return <ArrowUpDown className="ml-1 inline h-3 w-3 opacity-40" aria-hidden="true" />
  if (dir === 'asc') return <ArrowUp className="ml-1 inline h-3 w-3 text-foreground" aria-hidden="true" />
  return <ArrowDown className="ml-1 inline h-3 w-3 text-foreground" aria-hidden="true" />
}

interface SourceSplitBarProps {
  walkIn: number
  booked: number
  total: number
}

function SourceSplitBar({ walkIn, booked, total }: SourceSplitBarProps) {
  if (total === 0) return null
  const walkInPct = Math.round((walkIn / total) * 100)
  const bookedPct = 100 - walkInPct

  return (
    <div className="space-y-2">
      {/* Split bar */}
      <div
        className="flex h-3 w-full overflow-hidden rounded-full"
        role="img"
        aria-label={`Walk-in: ${walkInPct}%, Booked: ${bookedPct}%`}
      >
        <div
          className="h-full transition-all"
          style={{
            width: `${walkInPct}%`,
            backgroundColor: 'color-mix(in oklch, var(--color-stone) 55%, transparent)',
          }}
        />
        <div
          className="h-full transition-all"
          style={{
            width: `${bookedPct}%`,
            backgroundColor: 'color-mix(in oklch, var(--color-onyx) 75%, transparent)',
          }}
        />
      </div>

      {/* Labels */}
      <div className="flex justify-between text-xs text-muted-foreground">
        <span className="tabular-nums">
          Walk-in / in-person
          <span className="ml-1.5 font-semibold text-foreground tabular-nums">{walkIn}</span>
          <span className="ml-1 opacity-60">({walkInPct}%)</span>
        </span>
        <span className="tabular-nums">
          <span className="mr-1 opacity-60">({bookedPct}%)</span>
          <span className="mr-1.5 font-semibold text-foreground tabular-nums">{booked}</span>
          Pre-booked
        </span>
      </div>
    </div>
  )
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function buildStatusSegments(bd: StatusBreakdown): StatusSegment[] {
  return [
    { key: 'completed', label: 'Completed', count: bd.completed, tone: 'success' },
    { key: 'confirmed', label: 'Confirmed', count: bd.confirmed, tone: 'neutral' },
    { key: 'pending', label: 'Pending', count: bd.pending, tone: 'neutral' },
    { key: 'in_progress', label: 'In progress', count: bd.in_progress, tone: 'neutral' },
    { key: 'rescheduled', label: 'Rescheduled', count: bd.rescheduled, tone: 'neutral' },
    { key: 'no_show', label: 'No-show', count: bd.no_show, tone: 'destructive' },
    { key: 'cancelled', label: 'Cancelled', count: bd.cancelled, tone: 'destructive' },
  ]
}

function trendOf(delta: number | null): 'up' | 'down' | 'neutral' {
  if (delta === null) return 'neutral'
  return delta > 0 ? 'up' : delta < 0 ? 'down' : 'neutral'
}

// ─── Main component ───────────────────────────────────────────────────────────

export function BookingsReportClient() {
  const searchParams = useSearchParams()
  const from = searchParams.get('from') ?? ''
  const to = searchParams.get('to') ?? ''
  const compare = searchParams.get('compare') ?? '0'

  const [sortKey, setSortKey] = useState<SortKey>('count')
  const [sortDir, setSortDir] = useState<SortDir>('desc')

  const { data, isLoading, error } = useQuery<BookingsResponse>({
    queryKey: ['reports', 'bookings', from, to, compare],
    queryFn: () => {
      const params = new URLSearchParams()
      if (from) params.set('from', from)
      if (to) params.set('to', to)
      if (compare === '1') params.set('compare', '1')
      return fetch(`/api/reports/bookings?${params.toString()}`).then((r) => r.json())
    },
    staleTime: 5 * 60 * 1000,
  })

  const getRows = useCallback(() => {
    return (data?.current.timeline ?? []).map((r) => ({
      period: r.period,
      count: String(r.count),
    }))
  }, [data])

  useExportCsv({
    filename: 'analytics-bookings',
    getRows,
    headers: { period: 'Period', count: 'Bookings' },
  })

  function handleSort(key: SortKey) {
    if (sortKey === key) {
      setSortDir((prev) => (prev === 'desc' ? 'asc' : 'desc'))
    } else {
      setSortKey(key)
      setSortDir('desc')
    }
  }

  return (
    <DataState
      data={data}
      isLoading={isLoading}
      isError={!!error}
      error={error instanceof Error ? error : null}
      loadingSlot={<ChartSkeleton />}
      emptySlot={
        <EmptyState
          icon={CalendarDays}
          title="No booking data yet"
          description="Bookings will appear here once your first appointment is completed."
          variant="default"
        />
      }
    >
      {(resp) => {
        const d = resp.current
        const prior = resp.prior
        const kpis = d.kpis
        const priorKpis = prior?.kpis
        const bd = d.statusBreakdown
        const timelineForChart = d.timeline.map((r) => ({ name: r.period, value: r.count }))

        const completionRate =
          kpis.total > 0 ? Math.round((kpis.completed / kpis.total) * 100) : 0
        const noShowAndCancelled = kpis.noShows + kpis.cancelled
        const combinedRate =
          kpis.total > 0 ? Math.round((noShowAndCancelled / kpis.total) * 100) : 0

        const statusSegments = buildStatusSegments(bd)

        const showDeltas = compare === '1' && priorKpis !== undefined

        const totalDeltaRaw = computeDelta(kpis.total, priorKpis?.total)

        const completionRatePrior = priorKpis && priorKpis.total > 0
          ? Math.round((priorKpis.completed / priorKpis.total) * 100)
          : undefined
        const completionDeltaRaw = completionRatePrior !== undefined
          ? computeDelta(completionRate, completionRatePrior)
          : null

        const noShowPriorRaw = priorKpis ? priorKpis.noShows + priorKpis.cancelled : undefined
        const noShowDeltaRaw = noShowPriorRaw !== undefined
          ? computeDelta(noShowAndCancelled, noShowPriorRaw)
          : null

        const totalDelta = showDeltas ? formatPercent(totalDeltaRaw) : null
        const completionDelta = showDeltas ? formatPercent(completionDeltaRaw) : null
        const noShowDelta = showDeltas ? formatPercent(noShowDeltaRaw) : null

        const priorLabel = 'vs prior period'

        const priorTimelineForChart = prior?.timeline.map((r) => ({
          name: r.period,
          value: r.count,
        }))

        const sortedServices = sortServices(d.serviceRanking, sortKey, sortDir)

        return (
          <div className="space-y-6">
            {/* 3 KPI cards */}
            <div className="grid gap-4 sm:grid-cols-3">
              <KpiCard
                label="Total Bookings"
                value={kpis.total}
                subtextLabel={totalDelta ? priorLabel : 'in period'}
                icon={CalendarDays}
                trend={trendOf(totalDeltaRaw)}
                index={0}
                {...(totalDelta !== null ? { delta: totalDelta } : {})}
              />
              <KpiCard
                label="Completion Rate"
                value={`${completionRate}%`}
                subtextLabel={completionDelta ? priorLabel : `${kpis.completed} sessions completed`}
                icon={CalendarDays}
                trend={trendOf(completionDeltaRaw)}
                index={1}
                {...(completionDelta !== null ? { delta: completionDelta } : {})}
              />
              <KpiCard
                label="No-show + Cancelled"
                value={noShowAndCancelled}
                subtextLabel={noShowDelta ? priorLabel : `${combinedRate}% of total`}
                icon={TrendingDown}
                invertTrend
                trend={noShowAndCancelled > 0 ? trendOf(noShowDeltaRaw) : 'neutral'}
                accentVar="var(--color-rust)"
                index={2}
                {...(noShowDelta !== null ? { delta: noShowDelta } : {})}
              />
            </div>

            {/* Walk-in vs booked split */}
            <Card className="border-border/50 shadow-[var(--shadow-card)]">
              <CardHeader>
                <CardTitle className="text-sm font-medium">Walk-in vs Pre-booked</CardTitle>
              </CardHeader>
              <CardContent>
                {d.sourceBreakdown.total === 0 ? (
                  <EmptyState
                    icon={CalendarDays}
                    title="No source data"
                    description="Booking source data is not yet populated."
                    size="sm"
                    compact
                  />
                ) : (
                  <SourceSplitBar
                    walkIn={d.sourceBreakdown.walkIn}
                    booked={d.sourceBreakdown.booked}
                    total={d.sourceBreakdown.total}
                  />
                )}
              </CardContent>
            </Card>

            {/* Status breakdown */}
            <Card className="border-border/50 shadow-[var(--shadow-card)]">
              <CardHeader>
                <CardTitle className="text-sm font-medium">Status Breakdown</CardTitle>
              </CardHeader>
              <CardContent>
                <StatusBreakdownBar statuses={statusSegments} total={kpis.total} />
              </CardContent>
            </Card>

            {/* Timeline */}
            <Card className="border-border/50 shadow-[var(--shadow-card)]">
              <CardHeader>
                <CardTitle className="text-sm font-medium">Bookings Over Time</CardTitle>
              </CardHeader>
              <CardContent>
                {timelineForChart.length === 0 ? (
                  <EmptyState
                    icon={CalendarDays}
                    title="No booking data yet"
                    description="Bookings will appear here once created."
                  />
                ) : (
                  <RechartsBarChart
                    data={timelineForChart}
                    dataKey="value"
                    label="Bookings"
                    formatValue={(v) => `${v}`}
                    {...(priorTimelineForChart ? { priorData: priorTimelineForChart, priorLabel } : {})}
                  />
                )}
              </CardContent>
            </Card>

            {/* Heatmap */}
            <Card className="border-border/50 shadow-[var(--shadow-card)]">
              <CardHeader>
                <CardTitle className="text-sm font-medium">
                  Booking Heatmap — Day &times; Hour
                </CardTitle>
              </CardHeader>
              <CardContent>
                <BookingsHeatmap data={d.heatmap} />
              </CardContent>
            </Card>

            {/* Per-service detail table — sortable */}
            {sortedServices.length > 0 && (
              <Card className="border-border/50 shadow-[var(--shadow-card)]">
                <CardHeader>
                  <CardTitle className="text-sm font-medium">Services — Detail</CardTitle>
                </CardHeader>
                <CardContent className="p-0">
                  <div className="overflow-x-auto">
                    <table
                      className="w-full min-w-[580px] text-sm"
                      aria-label="Services detail table"
                    >
                      <thead>
                        <tr className="border-b border-border/50 text-left">
                          <th className="px-6 py-3 text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">
                            #
                          </th>
                          <th className="px-4 py-3 text-[11px] font-semibold uppercase tracking-wide text-muted-foreground">
                            Service
                          </th>
                          <th className="px-4 py-3 text-right">
                            <button
                              type="button"
                              onClick={() => handleSort('count')}
                              className="text-[11px] font-semibold uppercase tracking-wide text-muted-foreground hover:text-foreground transition-colors"
                              aria-label="Sort by bookings"
                            >
                              Bookings
                              <SortIcon active={sortKey === 'count'} dir={sortDir} />
                            </button>
                          </th>
                          <th className="px-4 py-3 text-right">
                            <button
                              type="button"
                              onClick={() => handleSort('revenueCents')}
                              className="text-[11px] font-semibold uppercase tracking-wide text-muted-foreground hover:text-foreground transition-colors"
                              aria-label="Sort by revenue"
                            >
                              Revenue
                              <SortIcon active={sortKey === 'revenueCents'} dir={sortDir} />
                            </button>
                          </th>
                          <th className="px-4 py-3 text-right">
                            <button
                              type="button"
                              onClick={() => handleSort('avgTicketCents')}
                              className="text-[11px] font-semibold uppercase tracking-wide text-muted-foreground hover:text-foreground transition-colors"
                              aria-label="Sort by average ticket"
                            >
                              Avg Ticket
                              <SortIcon active={sortKey === 'avgTicketCents'} dir={sortDir} />
                            </button>
                          </th>
                          <th className="px-4 py-3 text-right pr-6">
                            <button
                              type="button"
                              onClick={() => handleSort('noShowRate')}
                              className="text-[11px] font-semibold uppercase tracking-wide text-muted-foreground hover:text-foreground transition-colors"
                              aria-label="Sort by no-show rate"
                            >
                              No-show %
                              <SortIcon active={sortKey === 'noShowRate'} dir={sortDir} />
                            </button>
                          </th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-border/50">
                        {sortedServices.slice(0, 15).map((svc, i) => (
                          <tr key={svc.name} className="hover:bg-muted/30 transition-colors">
                            <td className="px-6 py-3 text-sm font-bold text-muted-foreground tabular-nums">
                              {i + 1}
                            </td>
                            <td className="max-w-[200px] truncate px-4 py-3 font-medium">
                              {svc.name}
                            </td>
                            <td className="px-4 py-3 text-right tabular-nums">
                              <Badge variant="secondary">{svc.count}</Badge>
                            </td>
                            <td className="px-4 py-3 text-right tabular-nums font-medium">
                              {svc.revenueCents > 0 ? formatCurrency(svc.revenueCents) : '—'}
                            </td>
                            <td className="px-4 py-3 text-right tabular-nums text-muted-foreground">
                              {svc.avgTicketCents > 0 ? formatCurrency(svc.avgTicketCents) : '—'}
                            </td>
                            <td className="px-4 py-3 pr-6 text-right tabular-nums">
                              {svc.noShowRate > 0 ? (
                                <span className="text-[var(--color-rust)] font-medium">
                                  {svc.noShowRate}%
                                </span>
                              ) : (
                                <span className="text-muted-foreground">0%</span>
                              )}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        )
      }}
    </DataState>
  )
}

